Reimplement the built-in `Pick<T, K>` utility type.

**Requirements:**
- Declare and export `MyPick<T, K>` so `K` can only be keys of `T`.
- `MyPick<T, K>` should produce a new object type containing only the properties of `T` whose keys are in `K`.

**Example:**
```ts
type A = MyPick<{ a: number; b: string }, 'a'>;
// => { a: number }
```

You can use the `Expect<Equal<..., ...>>` helpers in `type-utils.ts` to validate your type.

files.content:
// Type-level assertion helpers for ts-types-drills.
// Adapted from type-challenges (https://github.com/type-challenges/type-challenges) — MIT.

export type Expect<T extends true> = T;

export type Equal<X, Y> = (<T>() => T extends X ? 1 : 2) extends <T>() => T extends Y ? 1 : 2
  ? true
  : false;

export type NotEqual<X, Y> = Equal<X, Y> extends true ? false : true;

export type NotAny<T> = [T] extends [never] ? false : 0 extends 1 & T ? false : true;

import type { Expect, Equal } from './type-utils.js';

export type MyPick<T, K extends keyof T> = { [P in K]: T[P] };

type cases = [
  Expect<Equal<MyPick<{ a: number; b: string }, 'a'>, { a: number }>>,
  Expect<
    Equal<
      MyPick<{ a: number; b: string; c: boolean }, 'a' | 'c'>,
      { a: number; c: boolean }
    >
  >,
];

export type { cases };
